import heapq
def topKFrequent(nums, k):
    cnt = Counter(nums)
    h = []
    for x, f in cnt.items():
        heapq.heappush(h, (f, x))
        if len(h) > k:
            heapq.heappop(h)
    return [x for _, x in h]

