    for i in range(n):
        while 1 <= nums[i] <= n:
            destination = nums[i] - 1
            if nums[destination] == nums[i]:
                break
            nums[i], nums[destination] = nums[destination], nums[i]
    for i, value in enumerate(nums, 1):
        if value != i:
            return i
    return n + 1

def threeSum(nums):
    nums.sort()
    ans = []
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # 第一个数去重
        if nums[i] > 0:
            break  # 后面都更大，不可能和为0

        left, right = i + 1, n - 1

        while left < right:
            total = nums[i] + nums[left] + nums[right]

            if total < 0:
                left += 1  # 和太小，需要变大
            elif total > 0:
                right -= 1  # 和太大，需要变小
            else:
                ans.append([nums[i], nums[left], nums[right]])
                left += 1
                right -= 1

                while left < right and nums[left] == nums[left - 1]:
                    left += 1  # 左指针去重
                while left < right and nums[right] == nums[right + 1]:
                    right -= 1  # 右指针去重

    return ans

