def maxSlidingWindow(nums, k):
    q = deque()
    ans = []
    for r, x in enumerate(nums):
        while q and nums[q[-1]] <= x:
            q.pop()
        q.append(r)
        if q[0] <= r - k:
            q.popleft()
        if r >= k - 1:
            ans.append(nums[q[0]])
    return ans

from collections import Counter

def findAnagrams(s, p):
    if not p or len(p) > len(s):
        return []
    need = Counter(p)
    window = Counter()
    answer = []
    for right, char in enumerate(s):
        window[char] += 1
        if right >= len(p):
            outgoing = s[right - len(p)]
            window[outgoing] -= 1
            if window[outgoing] == 0:
                del window[outgoing]
        if right + 1 >= len(p) and window == need:
            answer.append(right - len(p) + 1)
    return answer

