def minWindow(s, t):
    if not t:
        return ""
    need = Counter(t)
    missing = len(t)
    left = best_start = 0
    best_length = len(s) + 1
    for right, char in enumerate(s):
        if char in need:
            if need[char] > 0:
                missing -= 1
            need[char] -= 1
        while missing == 0:
            length = right - left + 1
            if length < best_length:
                best_start, best_length = left, length
            outgoing = s[left]
            left += 1
            if outgoing in need:
                need[outgoing] += 1
                if need[outgoing] > 0:
                    missing += 1
    if best_length > len(s):
        return ""
    return s[best_start:best_start + best_length]

