def mergeKLists(lists):
    h = []
    for i, x in enumerate(lists):
        if x:
            heapq.heappush(h, (x.val, i, x))
    dummy = ListNode()
    cur = dummy
    while h:
        _, i, x = heapq.heappop(h)
        cur.next = x
        cur = cur.next
        if x.next:
            heapq.heappush(h, (x.next.val, i, x.next))
    return dummy.next

def dailyTemperatures(temperatures):
    ans = [0] * len(temperatures)  # 默认没有更高温就是 0
    stack = []  # 存“下标”

    for i, t in enumerate(temperatures):
        # 当前温度比栈顶那天高：栈顶的答案找到了
        while stack and t > temperatures[stack[-1]]:
            j = stack.pop()
            ans[j] = i - j  # 两天下标之差 = 等待天数

        stack.append(i)  # 当前天入栈，等待未来更高温

    return ans

class MinStack:
    def __init__(self):
        self.stack = []
        self.mn = []
    def push(self, x):
        self.stack.append(x)
        if not self.mn:
            self.mn.append(x)
        else:
            self.mn.append(min(x, self.mn[-1]))
    def pop(self):
        self.stack.pop()
        self.mn.pop()
    def top(self):
        return self.stack[-1]
    def getMin(self):
        return self.mn[-1]

def largestRectangleArea(nums):
    stack = []
    ans = 0
    a = nums + [0]
    for i, h in enumerate(a):
        while stack and a[stack[-1]] > h:
            height = a[stack.pop()]
            if stack:
                left = stack[-1]
            else:
                left = -1
            width = i - left - 1
            ans = max(ans, height * width)
        stack.append(i)
    return ans

