class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.cache = OrderedDict()  # 左边最旧，右边最新

    def get(self, key):
        if key not in self.cache:
            return -1

        self.cache.move_to_end(key)  # 访问过：移动到最右边
        return self.cache[key]

    def put(self, key, value):
        self.cache[key] = value  # 新增或更新 value
        self.cache.move_to_end(key)  # 标记为最近使用

        if len(self.cache) > self.cap:  # 超容量
            self.cache.popitem(last=False)  # 删除最左边：最久未使用

def maxDepth(root):
    if not root:
        return 0
    l = maxDepth(root.left)
    r = maxDepth(root.right)
    return 1 + max(l, r)

def traversal(root, order):
    result = []

    def visit(node):
        if node is None:
            return
        if order == "pre":
            result.append(node.val)
        visit(node.left)
        if order == "in":
            result.append(node.val)
        visit(node.right)
        if order == "post":
            result.append(node.val)

    visit(root)
    return result

def hasPathSum(root, target_sum):
    if root is None:
        return False
    if root.left is None and root.right is None:
        return root.val == target_sum
    remaining = target_sum - root.val
    return hasPathSum(root.left, remaining) or hasPathSum(root.right, remaining)

def lowestCommonAncestor(root, p, q):
    if not root or root == p or root == q:
        return root
    l = lowestCommonAncestor(root.left, p, q)
    r = lowestCommonAncestor(root.right, p, q)
    if l and r:
        return root
    return l or r

def maxPathSum(root):
    ans = float('-inf')
    def dfs(root):
        nonlocal ans
        if not root:
            return 0
        l = max(dfs(root.left), 0)
        r = max(dfs(root.right), 0)
        ans = max(ans, root.val + l + r)
        return root.val + max(l, r)
    dfs(root)
    return ans

def numIslands(grid):
    if not grid:
        return 0

    m, n = len(grid), len(grid[0])

    def dfs(i, j):
        # 越界，或者已经是水/访问过：停止
        if i < 0 or i >= m or j < 0 or j >= n:
            return
        if grid[i][j] != "1":
            return

        grid[i][j] = "0"  # 标记已访问：把陆地“淹掉”
        dfs(i + 1, j)  # 下
        dfs(i - 1, j)  # 上
        dfs(i, j + 1)  # 右
        dfs(i, j - 1)  # 左

    ans = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == "1": # 找到一座新岛的入口
                ans += 1
                dfs(i, j)  # 一次 DFS 淹掉整座岛

    return ans

from collections import deque

def courseOrder(num_courses, prerequisites):
    graph = [[] for _ in range(num_courses)]
    indegree = [0] * num_courses
    for course, prerequisite in prerequisites:
        graph[prerequisite].append(course)
        indegree[course] += 1
    ready = deque(i for i, degree in enumerate(indegree) if degree == 0)
    order = []
    while ready:
        current = ready.popleft()
        order.append(current)
        for course in graph[current]:
            indegree[course] -= 1
            if indegree[course] == 0:
                ready.append(course)
    return order if len(order) == num_courses else []

def canFinish(num_courses, prerequisites):
    return len(courseOrder(num_courses, prerequisites)) == num_courses

def bubbleSort(nums):
    for end in range(len(nums) - 1, 0, -1):
        changed = False
        for i in range(end):
            if nums[i] > nums[i + 1]:
                nums[i], nums[i + 1] = nums[i + 1], nums[i]
                changed = True
        if not changed:
            break
    return nums

