def quickSort(nums):
    def sort(left, right):
        if left >= right:
            return
        pivot = nums[randrange(left, right + 1)]
        low, i, high = left, left, right
        while i <= high:
            if nums[i] < pivot:
                nums[low], nums[i] = nums[i], nums[low]
                low += 1
                i += 1
            elif nums[i] > pivot:
                nums[i], nums[high] = nums[high], nums[i]
                high -= 1
            else:
                i += 1
        sort(left, low - 1)
        sort(high + 1, right)

    sort(0, len(nums) - 1)
    return nums

def search(nums, target):
