def searchRange(nums, target):
    def lower(x):
        l=0
        r = len(nums)
        while l < r:
            m = (l + r) // 2
            if nums[m] < x:
                l=m+1
            else:
                r=m
        return l
    l = lower(target)
    if l == len(nums) or nums[l] != target:
        return [-1, -1]
    r = lower(target + 1) - 1
    return [l, r]

def letterCombinations(digits):
    if not digits:
        return []
    mp = {'2':'abc', '3':'def', '4':'ghi', '5':'jkl',
        '6':'mno', '7':'pqrs', '8':'tuv', '9':'wxyz'}
    ans = []
    path = []
    def dfs(i):
        if i == len(digits):
            ans.append(''.join(path))
            return
