            dfs(i + 1)
            path.pop()
    dfs(0)
    return ans

def restoreIpAddresses(s):
    ans = []
    path = []

    def dfs(start):
        if len(path) == 4:  # 已经切出4段
            if start == len(s):
                ans.append('.'.join(path))
            return

        # 当前一段只可能取 1、2、3 个字符
        for length in range(1, 4):
            if start + length > len(s):
                break

            part = s[start:start + length]

            if len(part) > 1 and part[0] == '0':
                break  # "01"、"00" 都不合法
            if int(part) > 255:
                break

            path.append(part)  # 做选择
            dfs(start + length)
            path.pop()  # 撤销选择

    dfs(0)
    return ans

from bisect import bisect_left

def lengthOfLIS(nums):
    tails = []

    for x in nums:
        i = bisect_left(tails, x)  # 找第一个 >= x 的位置

        if i == len(tails):  # x 比所有结尾都大
            tails.append(x)  # 可以把长度增加 1
        else:
            tails[i] = x  # 用更小的 x 优化这个长度的结尾

    return len(tails)

def longestCommonSubsequence(a, b):
    m = len(a)
    n = len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def minPathSum(a):
    m = len(a)
    n = len(a[0])
    dp = [float('inf')] * n
    dp[0] = 0
    for i in range(m):
        for j in range(n):
            if j == 0:
                dp[j] = dp[j] + a[i][j]
            else:
                dp[j] = min(dp[j], dp[j - 1]) + a[i][j]
    return dp[-1]

def minDistance(a, b):
    m = len(a)
    n = len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]

def uniquePaths(m, n):
    dp = [1] * n
    for _ in range(1, m):
        for j in range(1, n):
            dp[j] += dp[j - 1]
    return dp[-1]

def wordBreak(s, wordDict):
    words = set(wordDict)
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True
    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in words:
                dp[i] = True
                break
    return dp[n]

def longestPalindrome(s):
    ans = ''
    for i in range(len(s)):
        for l, r in ((i, i), (i, i + 1)):
            while l >= 0 and r < len(s) and s[l] == s[r]:
                if r - l + 1 > len(ans):
                    ans = s[l:r + 1]
                l -= 1
                r += 1
    return ans

def canJump(nums):
    far = 0
    for i, x in enumerate(nums):
        if i > far:
            return False
        far = max(far, i + x)
    return True
